head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
scwin.clickID = "";
scwin.pMenuID = $c.cm.InfoMenuID();
//var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lcd.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
// dialog 호출용 함수
// 발행기관목록관련
scwin.vScrenID = "ULDSTF70002.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listLeadComIDAssgn";
    url += "&LEADCOM_MBR_NO=" + $c.stf.getObjectValue(cmb_LeadcomMbrNo);
    url += "&LD_MKT_TP_CD=" + scwin.fr_MktId;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_setID = function(obj) {
    scwin.clickID = dts_List.getCellData(eval(obj), "INTEG_USR_ID");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_OpenDetail = async function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setID(row);
        //secugrpId = dts_List.NameString(row, 'SECUGRP_ID');

    }
    await $c.frame.CreateDialogFrame("ULDSTF70003.gfm", "/digital/ULDSTF70003.gfm", "ID 관리", 200, 200, 560, 375, "window");
};
scwin.fn_set_code = function() {
    //지정자문인
    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listLeadCode";
    //dts_SearchLeadCom.DataID = "/digital/DigitalListinvstg.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listLeadCode&For=R";
    dts_SearchLeadCom.DataID = encodeURI(url);
    dts_SearchLeadCom.reset();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "지정자주문인 ID배정현황", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    //PanelToGroupBox(panel_Top);
    scwin.fn_set_code();
    scwin.fn_list_sync();
};
